// Function to safely extract JSON from AI text output
function parseAiOutput(input) {
  if (typeof input === 'object' && input !== null && input.is_booking_intent !== undefined) {
    return input;
  }

  let rawText = "";
  if (typeof input === 'string') {
    rawText = input;
  } else if (input && input.text) {
    rawText = input.text;
  } else if (input && input.output) {
    rawText = input.output;
  } else {
    rawText = JSON.stringify(input || {});
  }

  // Clean Markdown code blocks if present
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      return JSON.parse(jsonMatch[0]);
    } catch (e) {
      // Parsing failed
    }
  }
  return {};
}

// Safely parse Gemini Output
const rawAiInput = parseAiOutput(items[0].json);

// Extract values with strong fallbacks
const isBookingIntent = rawAiInput.is_booking_intent ?? true; // Default to true if booking intent is detected
const customerName = rawAiInput.customer_name || $('Telegram Trigger').item.json.message.from.first_name || "Customer";
const service = rawAiInput.service || "General Consultation";
const requestedDate = rawAiInput.requested_date || new Date().toISOString().split('T')[0];
const rawTimeInput = rawAiInput.requested_time;
const duration = parseInt(rawAiInput.duration_minutes) || 30;

let startTimeFormatted = null;
let endTimeFormatted = null;

// Handle 12h / 24h Time Parsing safely
if (rawTimeInput && rawTimeInput !== "null" && rawTimeInput !== "MISSING") {
  let rawTime = String(rawTimeInput).trim().toUpperCase();
  let hours = 14; // Default safe fallback
  let minutes = 0;

  if (rawTime.includes("PM") || rawTime.includes("AM")) {
    const isPM = rawTime.includes("PM");
    const cleanTime = rawTime.replace(/(AM|PM)/g, "").trim();
    const timeParts = cleanTime.split(":");
    hours = parseInt(timeParts[0]) || 12;
    minutes = parseInt(timeParts[1]) || 0;
    if (isPM && hours < 12) hours += 12;
    if (!isPM && hours === 12) hours = 0;
  } else if (rawTime.includes(":")) {
    const timeParts = rawTime.split(":");
    hours = parseInt(timeParts[0]) || 12;
    minutes = parseInt(timeParts[1]) || 0;
  }

  startTimeFormatted = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
  const startMinutesTotal = hours * 60 + minutes;
  const endMinutesTotal = startMinutesTotal + duration;
  const endHours = Math.floor(endMinutesTotal / 60);
  const endMins = endMinutesTotal % 60;
  endTimeFormatted = `${String(endHours).padStart(2, '0')}:${String(endMins).padStart(2, '0')}`;
}

return [{
  json: {
    is_booking_intent: isBookingIntent,
    customer_name: customerName,
    telegram_id: $('Telegram Trigger').item.json.message.from.id,
    service: service,
    requested_date: requestedDate,
    start_time: startTimeFormatted,
    end_time: endTimeFormatted,
    duration_minutes: duration
  }
}];

const request = $('Calculate End Time').item.json;
const rawItems = items.map(item => item.json);
const existingBookings = rawItems.filter(b => b && b['Booking ID']);

const workStart = "09:00";
const workEnd = "21:00";

let isAvailable = true;
let reason = "";

// 1. Check if intent is not booking (e.g. Greetings)
if (!request.is_booking_intent) {
  isAvailable = false;
  reason = "Hello! Please provide the date, time, and service you would like to book.";
}
// 2. Check if time is missing
else if (!request.start_time) {
  isAvailable = false;
  reason = "Please specify a valid time for your booking (e.g., 3:00 PM).";
}
// 3. Check business hours
else if (request.start_time < workStart || request.end_time > workEnd) {
  isAvailable = false;
  reason = `Available booking slots are only between ${workStart} and ${workEnd}.`;
}
// 4. Check conflicts
else {
  for (const booking of existingBookings) {
    if (booking.Status === "Cancelled" || !booking.Start_Time) continue;

    if (request.start_time < booking.End_Time && request.end_time > booking.Start_Time) {
      isAvailable = false;
      reason = `Requested time conflicts with an existing booking from ${booking.Start_Time} to ${booking.End_Time}.`;
      break;
    }
  }
}

return [{
  json: {
    customer_name: request.customer_name,
    telegram_id: request.telegram_id,
    service: request.service,
    requested_date: request.requested_date,
    start_time: request.start_time,
    end_time: request.end_time,
    duration_minutes: request.duration_minutes,
    is_available: isAvailable,
    conflict_reason: reason
  }
}];

